#include <stdio.h>

#define BUF 65536

int main(void){
    unsigned char buf[BUF];
    long lines = 0, words = 0, bytes = 0;
    size_t maxlen = 0, curlen = 0;
    int in_word = 0;
    enum { SPACE=1, TAB=2, NL=3, VT=4, FF=5, CR=6 };

    while (1){
        int n = fread(buf, 1, BUF, stdin);
        if (n == 0) break;
        bytes += n;

        for (int i = 0; i < n; i++){
            unsigned char c = buf[i];
            int ws = 0;
            switch(c){
                case ' ':   ws=SPACE; break;
                case '\t':  ws=TAB; break;
                case '\n':  ws=NL; break;
                case '\v':  ws=VT; break;
                case '\f':  ws=FF; break;
                case '\r':  ws=CR; break;
            }

            if (ws == NL){
                lines++;
                if (curlen > maxlen) maxlen = curlen;
                curlen = 0;
                in_word = 0;
            } else if (ws != 0){
                /* vertical tab, form feed, carriage return: end current word */
                in_word = 0;
                curlen++;
            } else {
                curlen++;
                if (in_word == 0){
                    words++;
                    in_word = 1;
                }
            }
        }
    }

    /* If there's remaining content after the last newline, it counts as a line */
    if (curlen > 0 || bytes == 0) {
        /* bytes == 0 means empty input: curlen is 0 but no lines printed yet;
           we still need one line count for zero-length "no newline" stream?
           No - zero bytes means zero newlines, zero output line of content.
           But curlen could be > 0 if file doesn't end with \n. */
        /* Actually re-think: the "current line" only exists during processing.
           After the loop: if we've seen any data and last char wasn't \n,
           that final segment still counts as a line - ALREADY counted in maxlen,
           but not yet in `lines`. So add 1 more line. */
        /* Wait - lines counts newlines. The spec says lines = number of \n bytes.
           But what about the last line without \n? That's a "line" for maxlen
           purposes but NOT a newline. Let me re-read... */

        /* Spec: "lines: the number of newline bytes (\n) in the input."
           Simple - just count newlines, nothing more. */
    }

    /* But we need to track whether the last processed byte was \n for maxlen correctness.
       The curlen > 0 check above means there's a partial line at end (no trailing \n).
       This doesn't add to lines count, but if this partial line is longest, it matters */

    /* Actually I already update maxlen when we see \n. What about the very last segment?
       If file ends without \n, curlen > 0 after loop but we never recorded it in maxlen. */
    if (curlen > maxlen) maxlen = curlen;

    printf("%ld %ld %ld %zu\n", lines, words, bytes, maxlen);
    return 0;
}

#include <stdio.h>

#define BUF 65536

int main(void){
    unsigned char buf[BUF];
    long lines = 0, words = 0, bytes = 0;
    size_t maxlen = 0, curlen = 0;
    int in_word = 0;

    while (1){
        int n = (int)fread(buf, 1, BUF, stdin);
        if (n == 0) break;
        bytes += n;

        for (int i = 0; i < n; i++){
            unsigned char c = buf[i];
            curlen++;

            if (c == '\n'){
                lines++;
                if (curlen > maxlen) maxlen = curlen - 1;
                curlen = 0;
                in_word = 0;
            } else {
                int is_ws = (c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r');
                if (!is_ws){
                    if (!in_word) words++;
                    in_word = 1;
                } else {
                    in_word = 0;
                }
            }
        }
    }

    if (curlen > maxlen) maxlen = curlen;

    printf("%ld %ld %ld %zu\n", lines, words, bytes, maxlen);
    return 0;
}

